import{at as e,it as t,o as n,yt as r}from"./chunks/framework.B-d2E8F-.js";var i=JSON.parse(`{"title":"Work produced with TeXRA","description":"","frontmatter":{},"headers":[],"relativePath":"work-using-texra.md","filePath":"work-using-texra.md"}`),a={name:`work-using-texra.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="work-produced-with-texra" tabindex="-1">Work produced with TeXRA <a class="header-anchor" href="#work-produced-with-texra" aria-label="Permalink to “Work produced with TeXRA”">​</a></h1><p>A non-exhaustive list of public projects and papers that used TeXRA. To add yours, open an issue or a pull request on the <a href="https://github.com/LionSR/TeXRA" target="_blank" rel="noreferrer">TeXRA repository</a>.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to “Projects”">​</a></h2><ul><li><a href="https://github.com/LionSR/TNLean" target="_blank" rel="noreferrer"><strong>TNLean</strong></a>: Lean 4 formalization of tensor-network theory, including matrix-product states and their canonical forms.</li><li><a href="https://github.com/LionSR/QICLean" target="_blank" rel="noreferrer"><strong>QICLean</strong></a>: Lean 4 formalization of quantum information and channels, including states, entanglement, channel representations, and entropy.</li><li><a href="https://github.com/LionSR/MIPStarRE" target="_blank" rel="noreferrer"><strong>MIPStarRE</strong></a>: Lean formalization of mathematics around $\\mathrm{MIP}^* = \\mathrm{RE}$.</li></ul><h2 id="papers" tabindex="-1">Papers <a class="header-anchor" href="#papers" aria-label="Permalink to “Papers”">​</a></h2><ul><li><a href="https://arxiv.org/abs/2506.06214" target="_blank" rel="noreferrer"><strong>Can Theoretical Physics Research Benefit from Language Agents?</strong></a>, Sirui Lu, Zhijing Jin, Terry Jingchen Zhang, Pavel Kos, J. Ignacio Cirac, and Bernhard Schölkopf (ICML 2026). The position paper behind TeXRA.</li><li><a href="https://arxiv.org/abs/2510.20728" target="_blank" rel="noreferrer"><strong>Co-Designing Quantum Codes with Transversal Diagonal Gates via Multi-Agent Systems</strong></a>, Xi He, Sirui Lu, and Bei Zeng (2025).</li><li><a href="https://arxiv.org/abs/2607.07857" target="_blank" rel="noreferrer"><strong>Multi-agent Autoformalization of Tensor Network Theory</strong></a>, Sirui Lu, Erickson Tjoa, and J. Ignacio Cirac (2026). The paper behind <a href="https://github.com/LionSR/TNLean" target="_blank" rel="noreferrer">TNLean</a>.</li><li><a href="https://arxiv.org/abs/2606.27386" target="_blank" rel="noreferrer"><strong>Agentic Publication Protocol: An Attempt to Modernize Scientific Publication</strong></a>, Sirui Lu and Xiao-Liang Qi (2026).</li><li><a href="https://arxiv.org/abs/2601.09131" target="_blank" rel="noreferrer"><strong>Bidirectional Decoding for Concatenated Quantum Hamming Codes</strong></a>, Chao Zhang, Zipeng Wu, Jiahui Wu, and Shilin Huang (2026).</li><li><a href="https://arxiv.org/abs/2606.27249" target="_blank" rel="noreferrer"><strong>Quantum computer architecture with ions in tweezer arrays</strong></a>, Benjamin F. Schiffer, Christopher Monroe, Peter Zoller, and J. Ignacio Cirac (2026).</li></ul>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};